const sleep=ms=>new Promise(r=>setTimeout(r,ms));
const BASE='https://www.elmercadodeorigen.com';
async function run(){
  const targets=await (await fetch('http://127.0.0.1:9242/json/list')).json();
  const target=targets.find(x=>x.type==='page');
  const ws=new WebSocket(target.webSocketDebuggerUrl);
  await new Promise((ok,bad)=>{ws.onopen=ok;ws.onerror=bad});
  let seq=0; const pending=new Map(); const exceptions=[]; const consoleErrors=[];
  ws.onmessage=e=>{const m=JSON.parse(e.data);if(m.method==='Runtime.exceptionThrown'){exceptions.push(m.params?.exceptionDetails?.exception?.description||m.params?.exceptionDetails?.text||'exception');return;}if(m.method==='Runtime.consoleAPICalled'&&m.params?.type==='error'){consoleErrors.push((m.params.args||[]).map(a=>a.value||a.description||'').join(' '));return;}if(!m.id||!pending.has(m.id))return;const q=pending.get(m.id);pending.delete(m.id);clearTimeout(q.timer);m.error?q.bad(m.error):q.ok(m.result||{});};
  const cmd=(method,params={},timeout=30000)=>new Promise((ok,bad)=>{const id=++seq,timer=setTimeout(()=>{pending.delete(id);bad(new Error(method+' timeout'));},timeout);pending.set(id,{ok,bad,timer});ws.send(JSON.stringify({id,method,params}));});
  await cmd('Page.enable'); await cmd('Runtime.enable'); await cmd('Network.enable');
  const E=async expr=>{const r=await cmd('Runtime.evaluate',{expression:expr,returnByValue:true,awaitPromise:true},30000);return r.result?.value};
  async function nav(path,wait=4500){await cmd('Page.navigate',{url:BASE+path+(path.includes('?')?'&':'?')+'emdo_catalog_audit='+Date.now()},30000);await sleep(wait);return snap();}
  async function snap(){return E(`(()=>{const visible=e=>{if(!e)return false;const s=getComputedStyle(e),r=e.getBoundingClientRect();return s.display!=='none'&&s.visibility!=='hidden'&&Number(s.opacity||1)>0&&r.width>1&&r.height>1};const ids=[];for(const e of document.querySelectorAll('li.product,.products .product')){let m=(e.className||'').match(/post-(\\d+)/),id=m?Number(m[1]):Number(e.querySelector('[data-product_id]')?.getAttribute('data-product_id')||0);if(id&&!ids.includes(id))ids.push(id)}const rc=(document.querySelector('.woocommerce-result-count')?.innerText||'').replace(/\\s+/g,' ').trim();const m=rc.match(/(?:of|de)\\s+(\\d+)\\s+(?:results|resultados)|^(?:Showing|Mostrando).*?(\\d+)\\s+(?:results|resultados)|^(\\d+)\\s+(?:results|resultados)/i);const total=m?Number(m[1]||m[2]||m[3]):null;const price=[...document.querySelectorAll('li.product .price,.products .product .price')].slice(0,8).map(e=>e.innerText.trim());const trigger=document.querySelector('[data-mdo-destination-open]');const text=(document.body?.innerText||'').replace(/\\s+/g,' ').trim();return {href:location.href,title:document.title,readyState:document.readyState,products:ids.length,ids,resultCount:rc,total,prices:price,destinationText:(trigger?.innerText||'').replace(/\\s+/g,' ').trim(),cookie:document.cookie,overlays:[...document.querySelectorAll('.blockUI,.blockOverlay,.preloader,.loader,.loading-overlay,[aria-busy="true"]')].filter(visible).map(e=>e.className||e.getAttribute('aria-busy')),text:text.slice(0,18000)};})()`)}
  async function clickSidebar(text){return E(`(()=>{const t=${JSON.stringify(text)}.toLowerCase();const roots=[...document.querySelectorAll('aside,.sidebar,.widget,.shop-widget,.woostify-filter-content,.site-content .shop-widget')];let candidates=[];for(const root of roots)candidates.push(...root.querySelectorAll('label,a,button'));const visible=e=>{const s=getComputedStyle(e),r=e.getBoundingClientRect();return s.display!=='none'&&s.visibility!=='hidden'&&r.width>1&&r.height>1};candidates=[...new Set(candidates)].filter(visible);let e=candidates.find(x=>(x.innerText||'').trim().toLowerCase()===t)||candidates.find(x=>(x.innerText||'').trim().toLowerCase().includes(t));if(!e)return {clicked:false,available:candidates.map(x=>(x.innerText||'').trim()).filter(Boolean).slice(0,80)};let target=e;if(e.tagName==='LABEL'&&e.htmlFor)target=document.getElementById(e.htmlFor)||e;target.click();return {clicked:true,text:(e.innerText||'').trim(),tag:target.tagName,href:target.href||''};})()`)}
  async function firstMetadataFilter(){return E(`(()=>{const roots=[...document.querySelectorAll('aside,.sidebar,.widget,.shop-widget,.woostify-filter-content')];const inputs=roots.flatMap(r=>[...r.querySelectorAll('input[type=checkbox],input[type=radio]')]);const visible=e=>{const s=getComputedStyle(e),r=e.getBoundingClientRect();return s.display!=='none'&&s.visibility!=='hidden'&&r.width>1&&r.height>1};const bad=/1957|hidalgo|tolecarnes|huerta|categor|productor|producer|vendor|precio|price/i;for(const i of inputs){if(!visible(i))continue;let lab=i.id?document.querySelector('label[for="'+CSS.escape(i.id)+'"]'):null;let text=(lab?.innerText||i.closest('label')?.innerText||i.name||'').replace(/\\s+/g,' ').trim();if(text&&!bad.test(text)){i.click();return {clicked:true,label:text,name:i.name,value:i.value}}}return {clicked:false,inputs:inputs.map(i=>({name:i.name,value:i.value,label:(i.id?document.querySelector('label[for="'+CSS.escape(i.id)+'"]')?.innerText:'')||i.closest('label')?.innerText||''})).slice(0,80)};})()`)}
  async function orderPrice(){return E(`(()=>{const s=document.querySelector('select.orderby');if(!s)return {ok:false};const o=[...s.options].find(o=>o.value==='price')||[...s.options].find(o=>/low|bajo/i.test(o.textContent));if(!o)return {ok:false,options:[...s.options].map(o=>[o.value,o.textContent.trim()])};s.value=o.value;s.dispatchEvent(new Event('change',{bubbles:true}));return {ok:true,value:o.value};})()`)}
  async function setDestination(code){return E(`(async()=>{const open=document.querySelector('[data-mdo-destination-open]');if(!open)return {ok:false,reason:'no trigger'};open.click();await new Promise(r=>setTimeout(r,300));const sel=document.querySelector('[data-mdo-destination-country]'),form=document.querySelector('[data-mdo-destination-form]');if(!sel||!form)return {ok:false,reason:'no form'};const options=[...sel.options].map(o=>[o.value,o.textContent.trim()]);if(!options.some(o=>o[0]===${JSON.stringify(code)}))return {ok:false,reason:'unsupported',options};sel.value=${JSON.stringify(code)};sel.dispatchEvent(new Event('change',{bubbles:true}));form.requestSubmit();return {ok:true,options};})()`)}
  async function waitReload(){for(let i=0;i<16;i++){await sleep(800);if(await E('document.readyState')==='complete'&&i>3)return;} }
  async function geom(path){await nav(path,3500);return E(`(()=>{const g=e=>{if(!e)return null;const b=e.getBoundingClientRect(),s=getComputedStyle(e);return {x:Math.round(b.x),y:Math.round(b.y),w:Math.round(b.width),h:Math.round(b.height),border:s.border,background:s.backgroundColor,borderRadius:s.borderRadius,fontSize:s.fontSize,lineHeight:s.lineHeight,padding:s.padding,color:s.color}};return {destination:g(document.querySelector('[data-mdo-destination-open]')),ordering:g(document.querySelector('select.orderby')),modalClose:g(document.querySelector('[data-mdo-destination-close]')),destinationText:(document.querySelector('[data-mdo-destination-open]')?.innerText||'').replace(/\\s+/g,' ').trim(),options:[...document.querySelectorAll('select.orderby option')].map(o=>o.textContent.trim())};})()`)}
  const out={tests:{},geometry:{},exceptions,consoleErrors};
  out.tests.es_shop=await nav('/tienda/');
  out.tests.en_shop=await nav('/en/shop/');
  out.tests.es_page2=await nav('/tienda/page/2/',8500);
  out.tests.en_page2=await nav('/en/shop/page/2/',8500);
  await nav('/tienda/',3500);out.tests.order_es_action=await orderPrice();await sleep(5000);out.tests.order_es=await snap();
  await nav('/en/shop/',3500);out.tests.order_en_action=await orderPrice();await sleep(5000);out.tests.order_en=await snap();
  out.tests.vendor_store_es=await nav('/tienda/1957/',4500);
  out.tests.vendor_store_en=await nav('/en/store/1957/',4500);
  await nav('/tienda/',3500);out.tests.vendor_filter_es_action=await clickSidebar('1957');await sleep(5000);out.tests.vendor_filter_es=await snap();
  await nav('/en/shop/',3500);out.tests.vendor_filter_en_action=await clickSidebar('1957');await sleep(5000);out.tests.vendor_filter_en=await snap();
  await nav('/tienda/',3500);out.tests.category_filter_es_action=await clickSidebar('Carnes');await sleep(5000);out.tests.category_filter_es=await snap();
  await nav('/en/shop/',3500);out.tests.category_filter_en_action=await clickSidebar('Meat');await sleep(5000);out.tests.category_filter_en=await snap();
  out.tests.meta_es_before=await nav('/categoria-producto/jamones-paletas/',4000);out.tests.meta_es_action=await firstMetadataFilter();await sleep(5000);out.tests.meta_es_after=await snap();
  out.tests.meta_en_before=await nav('/en/product-category/hams-and-shoulders/',4000);out.tests.meta_en_action=await firstMetadataFilter();await sleep(5000);out.tests.meta_en_after=await snap();
  await nav('/tienda/',3500);out.tests.pl_es_action=await setDestination('PL');await waitReload();await sleep(3500);out.tests.pl_es=await snap();
  await nav('/en/shop/',3500);out.tests.pl_en_action=await setDestination('PL');await waitReload();await sleep(3500);out.tests.pl_en=await snap();
  out.tests.pl_vendor_1957=await nav('/en/store/1957/',4000);
  await nav('/en/shop/',3000);out.tests.reset_action=await setDestination('ES');await waitReload();
  out.geometry.es_global=await geom('/tienda/');
  out.geometry.en_global=await geom('/en/shop/');
  out.geometry.es_vendor=await geom('/tienda/1957/');
  out.geometry.en_vendor=await geom('/en/store/1957/');
  console.log(JSON.stringify(out,null,2));ws.close();
}
run().catch(e=>{console.error(e);process.exit(1)});
